--
-- Written by scripts/rows-sql.mjs from 1 worker file(s). Every value is
-- printable ASCII and every row cites its book. Rows are keyed on their
-- portable identity, never an id; a row already held is left as it is.

INSERT OR IGNORE INTO gear (slug, name, system, category, weight_lbs, cost, cost_note, damage, is_mega_damage, range, payload, rate_of_fire, ar, sdc, mdc, description, source_book, vehicle_slug) VALUES
  ('ng-hex-grenade', 'Hex Grenade', 'rifts', 'weapon', NULL, 2500, '2,500 credits each. The same gas as one load for the Forester power armor''s shoulder dispenser costs 2,000 credits a cloud.', 'No damage; a toxic smoke cloud. Full effect: -2 to strike, parry, dodge and disarm, -4 on initiative, -6 on Perception Rolls, -2 melee attacks, Spd halved and -20% on skills. Save 16 or higher vs non-lethal toxin for half the penalties for 1D4 melee rounds and no lingering effects', 0, 'Thrown or launched; the cloud covers a 20 ft (6.1 m) radius', 'One cloud', NULL, NULL, NULL, NULL, 'A pre-Rifts chemical smoke weapon the Coalition States rediscovered and lately shared with Northern Gun: hexachloroethane with grained aluminum and zinc oxides, whose hydrochloric acid fumes pull moisture out of the air. Inhaled, it scorches the airways, leaving victims gasping, coughing and hoarse. The cloud lasts 1D4+3 melee rounds (half in a strong wind); the full penalties run 1D6+2 minutes after exposure, then half penalties for another 2D4x10 minutes for mortals. Mortal Mega-Damage creatures (Xiticix, dinosaurs, most animals and mortal monsters) take half the initial penalties and their lingering half lasts only 3D6 minutes. Dragons, beings of magic, a number of demons and many other supernatural foes take half penalties for half the time and nothing after, except those with keen noses (Loup Garou, Wendigo, Werebeasts and the like), who suffer the full initial effect and half for 1D6 minutes after. No effect on animated dead, undead, Elementals, beings immune to sulfur or toxic gas, fire breathers, or anyone inside sealed environmental armor or a sealed vehicle, robot or power armor. The Forester''s shoulder dispenser can be loaded with the same gas.', 'Rifts World Book 34: Northern Gun Two p.97-98', NULL),
  ('ng-x33-smoke-flare', 'Smoke Flare (Forester)', 'rifts', 'gear', NULL, 80, '80 credits each; twelve come with every Forester power armor.', 'None', 0, 'A column 1-2 ft (0.3 to 0.6 m) wide rising 400 ft (122 m), widening as it climbs', NULL, 'Setting off each flare counts as one melee action', NULL, NULL, NULL, 'A trail-marking and signal flare carried twelve to a bandoleer across the Forester power armor''s left side. It puts up a slow, slender plume of red, yellow or blue smoke for 20 minutes, which then lingers as a fading stripe for another 2D4 minutes (half that in winds over 8 mph/13 km). Teams often assign each color a meaning, such as a warning or a call to gather. More can be carried in belt pouches or a backpack.', 'Rifts World Book 34: Northern Gun Two p.98', NULL),
  ('ng-x33-electronic-trail-marker', 'Electronic Trail Marker (Forester)', 'rifts', 'gear', NULL, 200, '200 credits each as a replacement; twenty come with every Forester power armor, ten in each neck collar compartment.', NULL, 0, 'Transmits one mile (1.6 km)', '240 hours (10 days) of transmission', NULL, NULL, NULL, NULL, 'A small green beacon about half a credit card in size but triple its thickness, with a wire clip for hanging on a branch or under a leaf, tucking under a log or rock, or simply dropping. Every marker pings softly on the same preset, seldom-used radio band; the tone grows louder and shifts pitch within 2 ft (0.6 m) as a follower homes in, and fades if he strays off the path, so teammates who know the frequency can follow a trail no one else sees.', 'Rifts World Book 34: Northern Gun Two p.94-99', NULL),
  ('ng-x33-uv-paint-refill', 'Ultraviolet Paint Refill Canister (Forester)', 'rifts', 'gear', NULL, 20, '20 credits per refill canister.', NULL, 0, 'Sprayer reach 2 ft (0.6 m)', 'As much paint as a 12 ounce spray can holds', NULL, NULL, NULL, NULL, 'A refill for the ultraviolet paint sprayer in the Forester power armor''s left forearm. The paint cannot be seen by normal eyes but shows under black light or to ultraviolet optics, so arrows, symbols, coordinates or words can mark a trail only comrades will find, though creatures that see ultraviolet notice the marks too.', 'Rifts World Book 34: Northern Gun Two p.94 and 99', NULL),
  ('ng-ex10-helmet-light', 'Helmet Light (Gladius Light upgrade)', 'rifts', 'gear', NULL, 1200, '1,200 credits as an optional upgrade for the Gladius Light power armor.', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 'An extra-cost upgrade for the Gladius Light exo-skeleton: a miner''s-style lamp fitted to the top or one side of the helmet.', 'Rifts World Book 34: Northern Gun Two p.100', NULL),
  ('ng-ex10-head-cam', 'Head Cam (Gladius Light upgrade)', 'rifts', 'gear', NULL, 3500, '3,500 credits as an optional upgrade for the Gladius Light power armor.', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 'An extra-cost upgrade for the Gladius Light exo-skeleton: a dashboard-style digital camera fitted to the top or one side of the helmet, with room for 4,000 stills and 96 hours of video.', 'Rifts World Book 34: Northern Gun Two p.100', NULL),
  ('ng-ex10-language-translator', 'Built-In Language Translator (Gladius Light upgrade)', 'rifts', 'gear', NULL, 10000, '10,000 credits as an optional upgrade for the Gladius Light power armor.', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 'An extra-cost upgrade for the Gladius Light exo-skeleton: a standard language translator unit built into the helmet.', 'Rifts World Book 34: Northern Gun Two p.100', NULL),
  ('ng-ex10-voice-modulation', 'Voice Modulation (Gladius Light upgrade)', 'rifts', 'gear', NULL, 13500, '13,500 credits as an optional upgrade for the Gladius Light power armor.', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 'An extra-cost upgrade for the Gladius Light exo-skeleton: a helmet mouthpiece combining a bullhorn loudspeaker, a language translator and a voice modulator that disguises the wearer''s voice in 20 variations.', 'Rifts World Book 34: Northern Gun Two p.100', NULL);

-- Read the result back. This script asserts its OWN rows and nothing else.
SELECT 'all 8 gear rows are in' AS assertion, count(*) AS got, 8 AS want
  FROM gear WHERE slug IN ('ng-hex-grenade', 'ng-x33-smoke-flare', 'ng-x33-electronic-trail-marker', 'ng-x33-uv-paint-refill', 'ng-ex10-helmet-light', 'ng-ex10-head-cam', 'ng-ex10-language-translator', 'ng-ex10-voice-modulation') AND source_book IS NOT NULL;

